 "content": "def transform(grid):
    # Recolor the lower-area object to match the upper-area object while preserving shape.
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((color, cells))
    if len(objects) != 2:
        return [row[:] for row in grid]
    # In the example, the object with 6 is changed to 4, with its geometry unchanged.
    colors = {color for color, _ in objects}
    target = min(colors)
    out = [row[:] for row in grid]
    for color, cells in objects:
        if color != target:
            for r, c in cells:
                out[r][c] = target
    return out
