 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    src = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    marker = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not src or not marker:
        return out
    # The 6 object marks the axis and direction for reflecting the 4 object.
    for r, c in marker:
        out[r][c] = 0
    sr = sum(r for r, c in src) / len(src)
    sc = sum(c for r, c in src) / len(src)
    mr = sum(r for r, c in marker) / len(marker)
    mc = sum(c for r, c in marker) / len(marker)
    if abs(mc - sc) >= abs(mr - sr):
        axis2 = (min(c for r, c in src) + max(c for r, c in src))
        for r, c in src:
            cc = axis2 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    else:
        axis2 = min(r for r, c in src) + max(r for r, c in src)
        for r, c in src:
            rr = axis2 - r
            if 0 <= rr < h:
                out[rr][c] = 4
    return out
