        for r, c in src:
            cc = 2 * edge + (1 if mc > sc else -1) - c
            if 0 <= cc < w:
                out[r][cc] = 4
    else:
        edge = max(r for r, c in src) if mr > sr else min(r for r, c in src)
        for r, c in src:
            rr = 2 * edge + (1 if mr > sr else -1) - r
            if 0 <= rr < h:
                out[rr][c] = 4
